void swap(int *x, int *y)
{
    int temp = *x;
    *x = *y;
    *y = temp;
}

int a = 5, b = 7;
swap(&a, &b);
/* теперь a = 7, b = 5 */

void count_down(int n)
{
    if (n == 0)
        return;          /* базовый случай */
    printf("%i\n", n);
    count_down(n - 1);   /* меньшая задача */
}

int factorial(int n)
{
    if (n == 0)
        return 1;               /* базовый случай */
    int smaller = factorial(n - 1);
    return n * smaller;
}

int is_leap(int year) {
    if (year % 4 == 0)
        return 1;        /* 1900 останавливается здесь! */
    if (year % 100 == 0)
        return 0;
    if (year % 400 == 0) /* недостижимо */
        return 1;
    return 0;
}
/* фикс: проверять % 400, затем % 100, затем % 4 */

